export {
  createMidiInput,
  type MidiInput,
  type MidiInputState,
} from "./input";
export {
  DEFAULT_PITCH_BEND_RANGE,
  type MidiMessage,
  parseMidiMessage,
  pitchBendToSemitones,
} from "./message";

import { type MidiMessage, parseMidiMessage } from "./message";

/** What `createMidiInput` knows of the page's MIDI: whether it is supported and connected, the inputs, the muted ones, and why it is not connected. */
export interface MidiInputState {
  /** Whether a device is connected and its messages are coming in. */
  connected: boolean;
  /** Why it is not connected, when it is not: no Web MIDI, permission denied, no device. */
  error: string | null;
  /** The names of the connected devices. */
  inputs: string[];
  /** The names of the devices switched off with `setInputEnabled`: their messages are not heard. */
  muted: string[];
  /** Whether this browser has the Web MIDI API, which needs a secure context. */
  supported: boolean;
}

/** The page's MIDI inputs as one source: connect, listen to messages, switch inputs off, and follow its state. */
export interface MidiInput {
  /** Asks for access and listens to every input. Call it from a user gesture: browsers may prompt for permission. */
  connect: () => Promise<void>;
  /** Stops listening to every input. */
  disconnect: () => void;
  getServerSnapshot: () => MidiInputState;
  /** The current state: stable between changes, for `useSyncExternalStore` and the like. */
  getSnapshot: () => MidiInputState;
  /** Calls `handler` with each channel voice message of every connected input. Returns its unsubscribe. */
  listen: (handler: (message: MidiMessage) => void) => () => void;
  /** Switches the device named `name` off, so its messages are not heard, or on again. It holds before the device connects and while it is unplugged. */
  setInputEnabled: (name: string, enabled: boolean) => void;
  /** Calls `listener` when the state changes. Returns its unsubscribe. */
  subscribe: (listener: () => void) => () => void;
}

const UNSUPPORTED: MidiInputState = {
  connected: false,
  error: null,
  inputs: [],
  muted: [],
  supported: false,
};

const isSupported = () =>
  typeof navigator !== "undefined" &&
  typeof navigator.requestMIDIAccess === "function";

/**
 * The MIDI inputs of the page through the Web MIDI API, as one source: every
 * listener hears the messages of every connected device, and devices plugged
 * or unplugged later are picked up, and a device switched off with
 * `setInputEnabled` is not heard. System exclusive access is not asked for.
 * Make one and share it, so the browser is asked once.
 */
export function createMidiInput(): MidiInput {
  const handlers = new Set<(message: MidiMessage) => void>();
  const listeners = new Set<() => void>();
  const muted = new Set<string>();
  let access: MIDIAccess | null = null;
  let request = 0;
  let state: MidiInputState | null = null;

  const getSnapshot = () => {
    state ??= { ...UNSUPPORTED, supported: isSupported() };
    return state;
  };
  const update = (change: Partial<MidiInputState>) => {
    state = { ...getSnapshot(), ...change };
    for (const listener of listeners) {
      listener();
    }
  };

  const attach = () => {
    if (!access) {
      return;
    }
    const names: string[] = [];
    for (const input of access.inputs.values()) {
      const name = input.name ?? "MIDI device";
      input.onmidimessage = (event) => {
        if (muted.has(name)) {
          return;
        }
        const message = parseMidiMessage(event.data);
        if (message) {
          for (const handler of handlers) {
            handler(message);
          }
        }
      };
      names.push(name);
    }
    update({
      connected: names.length > 0,
      error: names.length > 0 ? null : "No MIDI device found.",
      inputs: names,
    });
  };

  const detach = () => {
    if (!access) {
      return;
    }
    access.onstatechange = null;
    for (const input of access.inputs.values()) {
      input.onmidimessage = null;
    }
    access = null;
  };

  return {
    connect: async () => {
      if (!isSupported()) {
        update({ error: "This browser has no Web MIDI." });
        return;
      }
      // A later connect or a disconnect makes this request's answer stale.
      request += 1;
      const asked = request;
      try {
        detach();
        const granted = await navigator.requestMIDIAccess({ sysex: false });
        if (asked !== request) {
          return;
        }
        access = granted;
        access.onstatechange = attach;
        attach();
      } catch {
        if (asked === request) {
          update({ error: "MIDI access was denied." });
        }
      }
    },
    disconnect: () => {
      request += 1;
      detach();
      update({ connected: false, error: null, inputs: [] });
    },
    getServerSnapshot: () => UNSUPPORTED,
    getSnapshot,
    setInputEnabled: (name, enabled) => {
      if (enabled === !muted.has(name)) {
        return;
      }
      if (enabled) {
        muted.delete(name);
      } else {
        muted.add(name);
      }
      update({ muted: [...muted] });
    },
    listen: (handler) => {
      handlers.add(handler);
      return () => {
        handlers.delete(handler);
      };
    },
    subscribe: (listener) => {
      listeners.add(listener);
      return () => {
        listeners.delete(listener);
      };
    },
  };
}

/**
 * Live MIDI 1.0 channel messages, as a Web MIDI input delivers them (one
 * message per event, a status byte then its data bytes). Values are
 * normalized the way the rest of audio/ui reads them: velocity and controller
 * values from 0 to 1, pitch bend from -1 to 1. The byte a device sent is
 * `Math.round(value * 127)`.
 */
export type MidiMessage =
  | {
      channel: number;
      /** The controller number: 1 is the mod wheel, 7 volume, 64 sustain, 123 all notes off. */
      controller: number;
      type: "controlchange";
      /** 0 to 1. A switch such as the sustain pedal is on from 0.5, the byte 64. */
      value: number;
    }
  | {
      channel: number;
      note: number;
      type: "noteoff";
      /** The release velocity, 0 to 1: 0 when a note-on with velocity 0 stood for the note-off. */
      velocity: number;
    }
  | { channel: number; note: number; type: "noteon"; velocity: number }
  | {
      channel: number;
      type: "pitchbend";
      /** -1 (wheel fully down) to 1 (fully up), 0 at rest. Both ends are reached. */
      value: number;
    };

const NOTE_OFF = 0x80;
const NOTE_ON = 0x90;
const CONTROL_CHANGE = 0xb0;
const PITCH_BEND = 0xe0;
const COMMAND_MASK = 0xf0;
const CHANNEL_MASK = 0x0f;
const DATA_BYTE_MAX = 127;
const PITCH_BEND_DATA_BITS = 7;
const PITCH_BEND_CENTER = 8192;
const PITCH_BEND_MAX = 16_383;

/** The bend range most synths start with, in semitones. A receiver sets its own, with RPN 0. */
export const DEFAULT_PITCH_BEND_RANGE = 2;

/**
 * Parses one channel voice message: note on, note off, control change or
 * pitch bend. `null` for everything else (program change, aftertouch, system
 * and real-time messages such as the clock) and for bytes that are not a
 * well-formed message: a data byte with its high bit set, or too few bytes.
 * A note-on with velocity 0 is a note-off, as the MIDI spec has it.
 */
export function parseMidiMessage(
  data: ArrayLike<number> | null | undefined
): MidiMessage | null {
  if (!data || data.length < 3) {
    return null;
  }
  const status = data[0] ?? 0;
  const first = data[1] ?? 0;
  const second = data[2] ?? 0;
  if (status < NOTE_OFF || first > DATA_BYTE_MAX || second > DATA_BYTE_MAX) {
    return null;
  }
  const channel = status & CHANNEL_MASK;
  switch (status & COMMAND_MASK) {
    case NOTE_ON:
      return second === 0
        ? { channel, note: first, type: "noteoff", velocity: 0 }
        : {
            channel,
            note: first,
            type: "noteon",
            velocity: second / DATA_BYTE_MAX,
          };
    case NOTE_OFF:
      return {
        channel,
        note: first,
        type: "noteoff",
        velocity: second / DATA_BYTE_MAX,
      };
    case CONTROL_CHANGE:
      return {
        channel,
        controller: first,
        type: "controlchange",
        value: second / DATA_BYTE_MAX,
      };
    case PITCH_BEND: {
      // 14 bits, the least significant seven first. The centre, 8192, is not
      // the middle of 0 to 16383, so each side is scaled to reach its own end.
      const raw = (second << PITCH_BEND_DATA_BITS) | first;
      const value =
        raw >= PITCH_BEND_CENTER
          ? (raw - PITCH_BEND_CENTER) / (PITCH_BEND_MAX - PITCH_BEND_CENTER)
          : (raw - PITCH_BEND_CENTER) / PITCH_BEND_CENTER;
      return { channel, type: "pitchbend", value };
    }
    default:
      return null;
  }
}

/** A pitch bend value in semitones, for a receiver whose bend range is `range` semitones each way. */
export function pitchBendToSemitones(
  value: number,
  range = DEFAULT_PITCH_BEND_RANGE
): number {
  return value * range;
}
